/** Hindi ordinal: पहला, दूसरा, तीसरा, चौथा, छठा; otherwise the number + वाँ */
export const hindiOrdinal = (n: number) =>
  ({ 1: "पहला", 2: "दूसरा", 3: "तीसरा", 4: "चौथा", 6: "छठा" } as Record<number, string>)[n] ?? `${HINDI[n]}वाँ`;

const EN_ONES = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve",
  "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];
const EN_TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];
/** English cardinal 1–100 */
export const english = (n: number): string =>
  n === 100 ? "one hundred" : n < 20 ? EN_ONES[n] : EN_TENS[Math.floor(n / 10)] + (n % 10 ? "-" + EN_ONES[n % 10] : "");
const EN_ORD: Record<string, string> = { one: "first", two: "second", three: "third", five: "fifth", eight: "eighth", nine: "ninth", twelve: "twelfth" };
/** English ordinal 1–100 */
export const englishOrdinal = (n: number): string => {
  const words = english(n).split("-");
  const last = words.pop()!;
  const ord = EN_ORD[last] ?? (last.endsWith("y") ? last.slice(0, -1) + "ieth" : last + "th");
  return [...words, ord].join("-");
};

